import json,sys
d=json.load(sys.stdin)
for e in d.get('entries',[]):
    print(e['type'], e['id'], e['name'])
    for k in ['created_by','modified_by','owned_by']:
        if k in e and e[k]:
            print(' ', k, e[k].get('id'), e[k].get('name'), e[k].get('login'))
